from fastapi import FastAPI, Form
from fastapi.testclient import TestClient
from pydantic import Json
from typing import Annotated
import pytest

app = FastAPI()

@app.post("/upload")
def upload(
    tags: Annotated[Json[list[str]], Form()]
):
    return {"tags": tags}

client = TestClient(app)

def test_json_list_form():
    # Client sends a JSON string in the form field
    # This is the core of the issue: FastAPI should treat it as a single string, not a list of strings.
    response = client.post(
        "/upload",
        data={"tags": '["abc", "def"]'}
    )
    assert response.status_code == 200
    assert response.json() == {"tags": ["abc", "def"]}

def test_json_list_form_failure():
    # Test with invalid JSON to ensure it still fails as expected (Pydantic validation)
    response = client.post(
        "/upload",
        data={"tags": 'not a json list'}
    )
    assert response.status_code == 422

def test_standard_list_form():
    # Ensure we didn't break standard list forms (non-Json)
    @app.post("/list")
    def list_route(items: Annotated[list[str], Form()]):
        return {"items": items}

    response = client.post(
        "/list",
        data={"items": ["a", "b"]}
    )
    assert response.status_code == 200
    assert response.json() == {"items": ["a", "b"]}

if __name__ == "__main__":
    try:
        test_json_list_form()
        print("test_json_list_form passed")
